INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 0, 1, "2020/04/30 12:00:00", "あたしだって\nやるときはやるよ！", 10040, 0, 24, 24001, 1, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 1, 1, "2020/04/30 12:00:00", "ふぅ…\nこれであたしの仕事は\n終わりだね", 10040, 0, 24, 24002, 1, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 2, 1, "2020/04/30 12:00:00", "終わった終わった\n一人でもなんとか\nなるもんだね", 10040, 0, 24, 24003, 1, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 3, 2, "2020/04/30 12:00:00", "やったね！\nこれでようやく\nサボれるよ…", 10040, 0, 24, 24004, 2, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 4, 1, "2020/04/30 12:00:00", "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 10040, 0, 24, 24005, 1, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 5, 2, "2020/04/30 12:00:00", "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 10040, 0, 24, 24006, 2, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 6, 2, "2020/04/30 12:00:00", "あたしも意外と\nやるもんでしょ？", 10040, 0, 24, 24007, 2, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 7, 4, "2020/04/30 12:00:00", "疲れた…\nねずみの逃げ足\n速すぎるよ…", 10040, 0, 24, 24008, 4, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 8, 4, "2020/04/30 12:00:00", "このままじゃ\nまっひ～に\n叱られちゃうよ", 10040, 0, 24, 24009, 4, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 9, 4, "2020/04/30 12:00:00", "まじめに\nやったんだけどな…\n悔しいな～", 10040, 0, 24, 24010, 4, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 10, 4, "2020/04/30 12:00:00", "やられた…\nねずみって意外と\nてごわいね", 10040, 0, 24, 24011, 4, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 11, 4, "2020/04/30 12:00:00", "おのれ～\nあたしのチーズを\n盗みやがって～！", 10040, 0, 24, 24012, 4, "2030/12/17 14:59:59", 102601, 0, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("リン", 12, 4, "2020/04/30 12:00:00", "疲れた…\nけど、次こそは\n守り抜くよ…", 10040, 0, 24, 24013, 1, "2030/12/17 14:59:59", 102601, 0, 1.81);
